const results = [];
const items = $input.all();

for (const item of items) {
  const g = item.json;

  if (!g.match_teams) continue;
  // Wild Dogs juega en FedePatin como equipo 'CONDORS'
  const isWildDogsGame = g.match_teams.some(mt => mt.teams && mt.teams.name && 
    (mt.teams.name.toUpperCase().includes('CONDORS') || mt.teams.name.toUpperCase().includes('WILD DOGS')));
  if (!isWildDogsGame) continue;

  const home = g.match_teams.find(mt => mt.side === 'home');
  const away = g.match_teams.find(mt => mt.side === 'away');

  const homeName = home && home.teams ? home.teams.name : 'Unknown';
  const awayName = away && away.teams ? away.teams.name : 'Unknown';
  const homeScore = home ? home.score_regular : null;
  const awayScore = away ? away.score_regular : null;

  const isHome = homeName.toUpperCase().includes('CONDORS') || homeName.toUpperCase().includes('WILD DOGS');
  const opponent = isHome ? awayName : homeName;
  const played = g.status === 'locked' || g.status === 'played' || g.status === 'finished';

  let result = null;
  if (played && homeScore !== null && awayScore !== null) {
    const wdScore = isHome ? homeScore : awayScore;
    const opScore = isHome ? awayScore : homeScore;
    result = wdScore > opScore ? 'win' : wdScore < opScore ? 'loss' : 'draw';
  }

  let divName = '';
  if (g.categories && g.categories.divisions) {
      divName = g.categories.divisions.name;
  }
  const catName = g.categories ? g.categories.name : '';
  const fullDivision = divName ? divName + ' - ' + catName : catName;

  results.push({
    json: {
      type: 'match',
      gameId: g.id,
      date: g.match_date ? g.match_date.split('T')[0] : null,
      time: g.match_date ? g.match_date.split('T')[1].substring(0, 5) : null,
      division: fullDivision,
      opponent: opponent,
      location: g.venue || null,
      homeScore: played ? homeScore : null,
      awayScore: played ? awayScore : null,
      result: result,
      status: g.status,
      isHome: isHome,
      notes: g.notes || null,
      timestamp: g.match_date
    }
  });
}
return results;

const results = [];
const items = $input.all();

for (const item of items) {
  const s = item.json;

  const teamName = s.teams ? s.teams.name : 'Unknown';

  let divName = '';
  if (s.categories && s.categories.divisions) {
      divName = s.categories.divisions.name;
  } else if (s.teams && s.teams.categories && s.teams.categories.divisions) {
      divName = s.teams.categories.divisions.name;
  }

  let catName = '';
  if (s.categories) {
      catName = s.categories.name;
  } else if (s.teams && s.teams.categories) {
      catName = s.teams.categories.name;
  }

  const fullDivision = divName ? divName + ' - ' + catName : catName;

  results.push({
    json: {
      type: 'standing',
      division: fullDivision,
      teamName: teamName,
      position: s.rank || 0,
      played: s.played || 0,
      won: s.wins || 0,
      drawn: s.draws || 0,
      lost: s.losses || 0,
      goalsFor: s.goals_for || 0,
      goalsAgainst: s.goals_against || 0,
      goalDifference: s.goal_diff || 0,
      points: s.points || 0
    }
  });
}
return results;

// Generate a deterministic UUID v4-like from a string seed
function seedUUID(seed) {
  let hash = 0;
  for (let i = 0; i < seed.length; i++) {
    const ch = seed.charCodeAt(i);
    hash = ((hash << 5) - hash) + ch;
    hash = hash & hash;
  }
  const hex = (n) => {
    const h = Math.abs(n).toString(16).padStart(8, '0');
    return h.substring(0, 8);
  };
  const h1 = hex(hash);
  const h2 = hex(hash * 31 + 7);
  const h3 = hex(hash * 37 + 13);
  const h4 = hex(hash * 41 + 17);
  return `${h1}-${h2.substring(0,4)}-4${h3.substring(1,4)}-a${h4.substring(1,4)}-${h2}${h3.substring(0,4)}`;
}

const items = $input.all();
const now = Date.now();
const steps = [];

for (const item of items) {
  const d = item.json;
  if (d.type === 'match') {
    const uuid = seedUUID('fp-match-' + d.gameId);
    // FedePatin: match_date llega en UTC desde Supabase (e.g. '2026-03-28T17:45:00')
    // Guardamos como UTC para que sea consistente con Fedehockey
    // En el frontend se muestra con toLocaleTimeString para convertir a hora local del usuario
    const rawDate = d.date && d.time ? d.date + 'T' + d.time + ':00Z' : null;
    const dateMs = rawDate ? new Date(rawDate).getTime() : now;
    steps.push(['update', 'matches', uuid, {
      gameId: String(d.gameId),
      date: dateMs,
      opponent: d.opponent,
      location: d.location,
      homeScore: d.homeScore,
      awayScore: d.awayScore,
      result: d.result,
      notes: (d.division || '') + (d.notes ? ' - ' + d.notes : ''),
      isHome: d.isHome || false,
      status: d.status || 'unknown',
      league: 'fedepatin',
      createdAt: now,
      updatedAt: now
    }]);
  } else if (d.type === 'standing') {
    const key = (d.division||'') + '-' + (d.teamName||'') + '-fp';
    const uuid = seedUUID('standing-' + key);
    steps.push(['update', 'standings', uuid, {
      teamName: d.teamName,
      division: d.division,
      position: d.position,
      played: d.played,
      won: d.won,
      drawn: d.drawn,
      lost: d.lost,
      goalsFor: d.goalsFor,
      goalsAgainst: d.goalsAgainst,
      goalDifference: d.goalDifference,
      points: d.points,
      league: 'fedepatin',
      updatedAt: now
    }]);
  }
}

return [{ json: { steps } }];
